private void checkIdle(final ChannelHandlerContext ctx) {
  if (paused()) {
    scheduleIdleCheck(ctx, idleTimeoutNanos);
    return;
  }
  final long remaining = idleTimeoutNanos - (clock.getAsLong() - lastActivity);
  if (remaining <= 0) {
    ctx.close();
  } else {
    scheduleIdleCheck(ctx, remaining);
  }
}
